CREATE TABLE IF NOT EXISTS children (
  id BIGINT PRIMARY KEY AUTO_INCREMENT, name VARCHAR(255) NOT NULL DEFAULT '小朋友', username VARCHAR(191) NULL DEFAULT NULL, avatar VARCHAR(32) NOT NULL DEFAULT '🚀', grade INT NOT NULL DEFAULT 5,
  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE IF NOT EXISTS words (id BIGINT PRIMARY KEY AUTO_INCREMENT, level INT NOT NULL DEFAULT 1, word VARCHAR(255) NOT NULL, meaning TEXT NOT NULL, phonetic VARCHAR(255) NOT NULL DEFAULT '', example TEXT NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, KEY idx_words_level (level));
CREATE TABLE IF NOT EXISTS word_progress (word_id BIGINT NOT NULL, child_id BIGINT NOT NULL, known TINYINT NOT NULL DEFAULT 0, last_reviewed TIMESTAMP NULL, PRIMARY KEY (word_id, child_id));
CREATE TABLE IF NOT EXISTS readings (id BIGINT PRIMARY KEY AUTO_INCREMENT, title VARCHAR(255) NOT NULL, content TEXT NOT NULL, level INT NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS reading_questions (id BIGINT PRIMARY KEY AUTO_INCREMENT, reading_id BIGINT NOT NULL, question TEXT NOT NULL, option_a TEXT NOT NULL, option_b TEXT NOT NULL, option_c TEXT NOT NULL, option_d TEXT NOT NULL, answer VARCHAR(255) NOT NULL, KEY idx_reading_q (reading_id));
CREATE TABLE IF NOT EXISTS math_problems (id BIGINT PRIMARY KEY AUTO_INCREMENT, level INT NOT NULL DEFAULT 1, type VARCHAR(100) NOT NULL, question TEXT NOT NULL, options TEXT NOT NULL, answer VARCHAR(255) NOT NULL, explanation TEXT NOT NULL, KEY idx_math_level (level));
CREATE TABLE IF NOT EXISTS tasks (id BIGINT PRIMARY KEY AUTO_INCREMENT, title VARCHAR(255) NOT NULL, type VARCHAR(100) NOT NULL, due_date DATE NULL, points INT NOT NULL DEFAULT 0, status VARCHAR(32) NOT NULL DEFAULT 'pending', child_id BIGINT NOT NULL DEFAULT 1, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, completed_at TIMESTAMP NULL, KEY idx_tasks_due (due_date), KEY idx_tasks_child (child_id));
CREATE TABLE IF NOT EXISTS points_log (id BIGINT PRIMARY KEY AUTO_INCREMENT, child_id BIGINT NOT NULL, delta INT NOT NULL DEFAULT 0, reason VARCHAR(255) NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, KEY idx_points_child (child_id));
CREATE TABLE IF NOT EXISTS rewards (id BIGINT PRIMARY KEY AUTO_INCREMENT, name VARCHAR(255) NOT NULL, cost_points INT NOT NULL DEFAULT 0, status VARCHAR(32) NOT NULL DEFAULT 'active');
CREATE TABLE IF NOT EXISTS redemptions (id BIGINT PRIMARY KEY AUTO_INCREMENT, reward_id BIGINT NOT NULL, child_id BIGINT NOT NULL DEFAULT 1, status VARCHAR(32) NOT NULL DEFAULT 'pending', requested_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, confirmed_at TIMESTAMP NULL, KEY idx_redemptions_child (child_id));
CREATE TABLE IF NOT EXISTS settings (`key` VARCHAR(255) PRIMARY KEY, value TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS parents (id BIGINT PRIMARY KEY AUTO_INCREMENT, casdoor_sub VARCHAR(255) NOT NULL UNIQUE, display_name VARCHAR(255) NOT NULL DEFAULT '', avatar VARCHAR(255) NOT NULL DEFAULT '', created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, last_login_at TIMESTAMP NULL);
CREATE TABLE IF NOT EXISTS practice_sessions (id BIGINT PRIMARY KEY AUTO_INCREMENT, child_id BIGINT NOT NULL DEFAULT 1, subject VARCHAR(32) NOT NULL, level INT NOT NULL DEFAULT 1, total INT NOT NULL DEFAULT 0, correct INT NOT NULL DEFAULT 0, max_combo INT NOT NULL DEFAULT 0, bonus INT NOT NULL DEFAULT 0, stars INT NOT NULL DEFAULT 0, finished TINYINT NOT NULL DEFAULT 0, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, finished_at TIMESTAMP NULL, KEY idx_sessions_child (child_id), KEY idx_sessions_subject (child_id, subject));
CREATE TABLE IF NOT EXISTS session_answers (id BIGINT PRIMARY KEY AUTO_INCREMENT, session_id BIGINT NOT NULL, ref_id BIGINT NOT NULL, correct TINYINT NOT NULL DEFAULT 0, points INT NOT NULL DEFAULT 0, combo INT NOT NULL DEFAULT 0, answered_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, KEY idx_session_answers (session_id));

-- 用户名唯一：NULL（未设置）不参与唯一约束，非空用户名必须唯一
CREATE UNIQUE INDEX idx_children_username ON children(username);
